primaryQuery:
run: order_items -> {
  group_by: order_id
  aggregate:
    lines is count()
    returned_lines is count() { where: status = 'Returned' }
} -> {
  aggregate:
    returned_orders is count() { where: returned_lines > 0 }
    fully_returned_orders is count() { where: returned_lines = lines }
    partially_returned_orders is count() { where: returned_lines > 0 and returned_lines < lines }
}

verifyQuery:
run: order_items -> {
  group_by: order_id, status
  aggregate: n is count()
} -> {
  group_by: order_id
  aggregate:
    distinct_statuses is count()
    returned_status_rows is count() { where: status = 'Returned' }
} -> {
  aggregate:
    returned_orders is count() { where: returned_status_rows > 0 }
    fully_returned_orders is count() { where: returned_status_rows > 0 and distinct_statuses = 1 }
    partially_returned_orders is count() { where: returned_status_rows > 0 and distinct_statuses > 1 }
}
